from flask import Flask, request, jsonify
from flask_jwt_extended import JWTManager, create_access_token, jwt_required, get_jwt_identity
from datetime import timedelta
import os

app = Flask(__name__)
app.config['JWT_SECRET_KEY'] = os.environ['{{secret_env}}']
app.config['JWT_ACCESS_TOKEN_EXPIRES'] = timedelta(minutes={{token_ttl_min}})
jwt = JWTManager(app)

@app.post('/login')
def login():
    data = request.get_json() or {}
    if not data.get('username') or not data.get('password'):
        return jsonify(error='missing creds'), 400
    return jsonify(token=create_access_token(identity=data['username']))

@app.get('/me')
@jwt_required()
def me():
    return jsonify(user=get_jwt_identity())
